package com.englishhero.practice;
import java.util.*;
import java.time.Instant;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;
import static com.englishhero.practice.PracticeDtos.*;
@Repository
public class PracticeSetMapper {
 final JdbcTemplate jdbc;
 public PracticeSetMapper(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public record Row(long id,long articleId,long articleVersionId,long quizId,String exam,String readingType,String metadata,Long publishedVersionId,String status,int revision,int lockVersion){}
 public record Version(long id,long setId,int revision,long articleId,long articleVersionId,long quizId,long quizVersionId,String metadata,String readingType,String wordBankJson,Instant publishedAt){}
 private final RowMapper<Row> rows=(r,n)->new Row(r.getLong("id"),r.getLong("article_id"),r.getLong("draft_article_version_id"),r.getLong("draft_quiz_id"),r.getString("exam_code"),r.getString("reading_type"),r.getString("draft_metadata_json"),r.getObject("published_version_id",Long.class),r.getString("status"),r.getInt("revision"),r.getInt("lock_version"));
 private final RowMapper<Version> versions=(r,n)->new Version(r.getLong("id"),r.getLong("set_id"),r.getInt("version_no"),r.getLong("article_id"),r.getLong("article_version_id"),r.getLong("quiz_id"),r.getLong("quiz_version_id"),r.getString("metadata_json"),r.getString("reading_type"),r.getString("word_bank_json"),r.getTimestamp("published_at").toInstant());
 public Row get(long id,boolean lock){return jdbc.query("SELECT * FROM practice_set WHERE id=?"+(lock?" FOR UPDATE":""),rows,id).stream().findFirst().orElse(null);}
 public Row forArticle(long article){return jdbc.query("SELECT * FROM practice_set WHERE article_id=? AND exam_code='CET4'",rows,article).stream().findFirst().orElse(null);}
 public Version version(long id){return jdbc.query("SELECT * FROM practice_set_version WHERE id=?",versions,id).stream().findFirst().orElse(null);}
 public String subjective(long id,boolean published){return jdbc.queryForObject("SELECT subjective_json FROM "+(published?"practice_set_version":"practice_set")+" WHERE id=?",String.class,id);}
 public String listening(long id){return jdbc.queryForObject("SELECT listening_json FROM practice_set_version WHERE id=?",String.class,id);}
 public Version revision(long id,int revision){return jdbc.query("SELECT * FROM practice_set_version WHERE set_id=? AND version_no=?",versions,id,revision).stream().findFirst().orElse(null);}
 public List<Version> versions(long id,int page,int size){return jdbc.query("SELECT * FROM practice_set_version WHERE set_id=? ORDER BY version_no DESC LIMIT ? OFFSET ?",versions,id,size,(page-1)*size);}
 long insert(String sql,Object...args){var key=new GeneratedKeyHolder();jdbc.update(c->{var s=c.prepareStatement(sql,java.sql.Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},key);return Objects.requireNonNull(key.getKey()).longValue();}
 public long create(long article,long version,long quiz,String readingType,String metadata,long actor){return insert("INSERT INTO practice_set(article_id,exam_code,reading_type,section,draft_article_version_id,draft_quiz_id,draft_metadata_json,created_by,updated_by) VALUES(?,'CET4',?,?,?,?,?,?,?)",article,readingType,"LISTENING".equals(readingType)?"LISTENING":"READING",version,quiz,metadata,actor,actor);}
 public void save(Row r,long version,long quiz,String metadata,long actor){jdbc.update("UPDATE practice_set SET draft_article_version_id=?,draft_quiz_id=?,draft_metadata_json=?,lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",version,quiz,metadata,actor,r.id());}
 public void review(Row r,String state,long actor){save(r,r.articleVersionId(),r.quizId(),state,actor);}
 public void publish(Row r,long quizVersion,String readingType,String wordBankJson,String metadata,long actor,ListeningData listening){long v=insert("INSERT INTO practice_set_version(set_id,version_no,article_id,article_version_id,quiz_id,quiz_version_id,reading_type,word_bank_json,metadata_json,created_by,listening_json,audio_asset_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",r.id(),r.revision()+1,r.articleId(),r.articleVersionId(),r.quizId(),quizVersion,readingType,wordBankJson,metadata,actor,listening==null?null:new tools.jackson.databind.ObjectMapper().writeValueAsString(listening),listening==null?null:Long.valueOf(listening.audioAssetId()));jdbc.update("UPDATE practice_set SET published_version_id=?,status='PUBLISHED',revision=revision+1,lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",v,actor,r.id());}
 public void publish(Row r,long quizVersion,String readingType,String wordBankJson,String metadata,long actor){publish(r,quizVersion,readingType,wordBankJson,metadata,actor,null);}
 public void unpublish(Row r,long actor){jdbc.update("UPDATE practice_set SET status='UNLISTED',lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",actor,r.id());}
 private record Sql(String from,List<Object> args){}
 private Sql filter(Query q,boolean admin,Long user,String exclude){var args=new ArrayList<Object>();String join=" FROM practice_set s JOIN reading_article a ON a.id=s.article_id LEFT JOIN reading_quiz z ON z.id=s.draft_quiz_id LEFT JOIN practice_set_version v ON v.id=s.published_version_id WHERE 1=1";if(!admin)join+=" AND s.status='PUBLISHED'";if("all".equals(q.section())){}else if(q.section()!=null&&!q.section().isBlank()){join+=" AND s.section=?";args.add(q.section().toUpperCase(java.util.Locale.ROOT));}else if(!admin)join+=" AND s.section='READING'";
  String meta=admin?"s.draft_metadata_json":"v.metadata_json",prefix=admin?"$.metadata.":"$.";
  var fields=new LinkedHashMap<String,String>();fields.put("exam","s.exam_code");fields.put("readingType","s.reading_type");fields.put("source","JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"sourceKind'))");fields.put("topic","JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"topic'))");fields.put("year","JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"year'))");fields.put("month","JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"month'))");fields.put("paperNo","JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"paperNo'))");if(admin)fields.put("status","s.status");
  var values=new HashMap<String,Object>();values.put("exam",q.exam());values.put("readingType",q.readingType());values.put("source",q.source());values.put("topic",q.topic());values.put("year",q.year());values.put("month",q.month());values.put("paperNo",q.paperNo());values.put("status",q.status());
  for(var f:fields.entrySet()){var value=values.get(f.getKey());if(!f.getKey().equals(exclude)&&value!=null&&!value.toString().isBlank()){join+=" AND "+f.getValue()+"=?";args.add(value);}}
  if(q.q()!=null&&!q.q().isBlank()){join+=" AND (JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"title')) LIKE ? ESCAPE '!' OR JSON_UNQUOTE(JSON_EXTRACT("+meta+",'"+prefix+"titleZh')) LIKE ? ESCAPE '!')";String t="%"+q.q().replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.add(t);args.add(t);}
  if(!admin&&!"state".equals(exclude)&&q.state()!=null&&!q.state().isBlank()&&!q.state().equals("ALL")){join+=" AND "+stateSql(user)+"=?";args.add(q.state());}
  return new Sql(join,args);
 }
 private String stateSql(Long user){if(user==null)return "'NOT_STARTED'";return "CASE WHEN s.reading_type IN ('WRITING','TRANSLATION') THEN CASE WHEN EXISTS(SELECT 1 FROM practice_subjective_attempt t WHERE t.user_id="+user+" AND t.set_id=s.id AND t.status='IN_PROGRESS') THEN 'IN_PROGRESS' WHEN EXISTS(SELECT 1 FROM practice_subjective_attempt t WHERE t.user_id="+user+" AND t.set_id=s.id AND t.status='COMPLETED') THEN 'COMPLETED' ELSE 'NOT_STARTED' END WHEN EXISTS(SELECT 1 FROM practice_attempt t WHERE t.user_id="+user+" AND t.set_id=s.id AND t.status='IN_PROGRESS') THEN 'IN_PROGRESS' WHEN EXISTS(SELECT 1 FROM practice_attempt t WHERE t.user_id="+user+" AND t.set_id=s.id AND t.kind='FULL' AND t.status='COMPLETED') THEN 'COMPLETED' ELSE 'NOT_STARTED' END";}
 public List<Row> list(Query q,boolean admin,Long user){var f=filter(q,admin,user,null);var args=new ArrayList<>(f.args());args.add(q.pageSize());args.add((q.page()-1)*q.pageSize());String order=switch(q.sort()==null?"":q.sort()){case "TITLE"->"JSON_UNQUOTE(JSON_EXTRACT("+(admin?"s.draft_metadata_json,'$.metadata.title'":"v.metadata_json,'$.title'")+")) ASC,s.id ASC";case "COUNT"->"COALESCE(JSON_LENGTH(z.draft_json),1) DESC,s.id DESC";default->admin?"s.created_at DESC,s.id DESC":"v.published_at DESC,s.id DESC";};return jdbc.query("SELECT s.*"+f.from()+" ORDER BY "+order+" LIMIT ? OFFSET ?",rows,args.toArray());}
 public long count(Query q,boolean admin,Long user){var f=filter(q,admin,user,null);return jdbc.queryForObject("SELECT COUNT(*)"+f.from(),Long.class,f.args().toArray());}
 public String state(long set,Long user){if(user==null)return null;return jdbc.queryForObject("SELECT "+stateSql(user)+" FROM practice_set s WHERE s.id=?",String.class,set);}
 public String current(long set,Long user){if(user==null)return null;return jdbc.queryForList("SELECT id FROM (SELECT id,set_id,user_id,status,started_at FROM practice_attempt UNION ALL SELECT id,set_id,user_id,status,started_at FROM practice_subjective_attempt) t WHERE set_id=? AND user_id=? AND status='IN_PROGRESS' ORDER BY started_at DESC,id DESC LIMIT 1",String.class,set,user).stream().findFirst().orElse(null);}
 public List<Map<String,Object>> facet(Query q,Long user,String field){var f=filter(q,false,user,field);String expression=switch(field){case "source"->"JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.sourceKind'))";case "readingType"->"s.reading_type";case "state"->stateSql(user);case "topic","year","month","paperNo"->"JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$."+field+"'))";default->throw new IllegalArgumentException();};return jdbc.query("SELECT "+expression+" value,COUNT(*) n"+f.from()+" GROUP BY value ORDER BY value",(r,n)->{String value=r.getString("value");return Map.<String,Object>of("value",value==null?"":value,"count",r.getLong("n"));},f.args().toArray()).stream().filter(v->!v.get("value").equals("")&&!v.get("value").equals("null")).toList();}
}
